bool exist(vector<vector<char>>& board, string word) {
    int m = board.size(), n = board[0].size();
    int dirs[4][2] = {{0,1},{1,0},{0,-1},{-1,0}};
    function<bool(int,int,int)> dfs = [&](int r, int c, int i) {
        if (i == word.size()) return true;
        if (r<0||r>=m||c<0||c>=n||board[r][c]!=word[i]) return false;
        char ch = board[r][c]; board[r][c] = '.';
        for (int d = 0; d < 4; d++) if (dfs(r+dirs[d][0], c+dirs[d][1], i+1)) return true;
        board[r][c] = ch; return false;
    };
    for (int r=0;r<m;r++) for (int c=0;c<n;c++) if (dfs(r,c,0)) return true;
    return false;
}
